// Test_UnitCertReloadParity checks that the reload handlers issue certificates with the same
// fields as the ones generated by deps.GenServerDeps at startup, using the key from the CSR.
func Test_UnitCertReloadParity(t *testing.T) {
	g := NewWithT(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	control := &config.Control{
		Token:          "token",
		ServerNodeName: "k3s-server-1",
		SANs:           []string{"tls-san.example.com", "127.0.0.1", "::1", "localhost", "k3s-server-1", "192.0.2.10"},
	}
	control.ClusterDomain = "cluster.local"
	control.ServiceIPRange = testutil.ServiceIPNet()
	os.Setenv("NODE_NAME", control.ServerNodeName)
	defer os.Unsetenv("NODE_NAME")
	control.DataDir = t.TempDir()
	g.Expect(testutil.GenerateRuntime(control)).To(Succeed())
	defer testutil.CleanupDataDir(control)

	// the supervisor listener adds the kubernetes service names to the SANs after startup
	control.SANs = append(control.SANs, "kubernetes", "kubernetes.default", "kubernetes.default.svc", "kubernetes.default.svc.cluster.local")

	auth, err := authenticator.FromArgs([]string{"--basic-auth-file=" + control.Runtime.PasswdFile})
	g.Expect(err).ToNot(HaveOccurred())
	control.Runtime.Authenticator = auth
	control.Runtime.Handler = NewHandler(ctx, control, &cmds.Server{})

	rt := control.Runtime
	tests := []struct {
		name, certFile, keyFile, caFile string
	}{
		{"serving-kube-apiserver", rt.ServingKubeAPICert, rt.ServingKubeAPIKey, rt.ServerCA},
		{"serving-kube-scheduler", rt.ServingKubeSchedulerCert, rt.ServingKubeSchedulerKey, rt.ServerCA},
		{"serving-kube-controller-manager", rt.ServingKubeControllerCert, rt.ServingKubeControllerKey, rt.ServerCA},
		{"serving-etcd-server", rt.ServerETCDCert, rt.ServerETCDKey, rt.ETCDServerCA},
		{"serving-etcd-peer", rt.PeerServerClientETCDCert, rt.PeerServerClientETCDKey, rt.ETCDPeerCA},
		{"client-etcd", rt.ClientETCDCert, rt.ClientETCDKey, rt.ETCDServerCA},
		{"client-admin", rt.ClientAdminCert, rt.ClientAdminKey, rt.ClientCA},
		{"client-supervisor", rt.ClientSupervisorCert, rt.ClientSupervisorKey, rt.ClientCA},
		{"client-controller", rt.ClientControllerCert, rt.ClientControllerKey, rt.ClientCA},
		{"client-scheduler", rt.ClientSchedulerCert, rt.ClientSchedulerKey, rt.ClientCA},
		{"client-kube-apiserver", rt.ClientKubeAPICert, rt.ClientKubeAPIKey, rt.ClientCA},
		{"client-cloud-controller", rt.ClientCloudControllerCert, rt.ClientCloudControllerKey, rt.ClientCA},
		{"client-auth-proxy", rt.ClientAuthProxyCert, rt.ClientAuthProxyKey, rt.RequestHeaderCA},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			g := NewWithT(t)
			startup, err := certutil.CertsFromFile(tt.certFile)
			g.Expect(err).ToNot(HaveOccurred())
			caCerts, err := certutil.CertsFromFile(tt.caFile)
			g.Expect(err).ToNot(HaveOccurred())
			key, err := certutil.PrivateKeyFromFile(tt.keyFile)
			g.Expect(err).ToNot(HaveOccurred())
			csr, err := x509.CreateCertificateRequest(rand.Reader, &x509.CertificateRequest{}, key)
			g.Expect(err).ToNot(HaveOccurred())

			req := httptest.NewRequest(http.MethodPost, CertReloadPath(tt.name), bytes.NewReader(csr))
			withClientAddress(req, "127.0.0.1")
			req.SetBasicAuth("server", control.Token)
			resp := httptest.NewRecorder()
			control.Runtime.Handler.ServeHTTP(resp, req)
			g.Expect(resp).To(HaveHTTPStatus(http.StatusOK))

			certs, err := certutil.ParseCertsPEM(resp.Body.Bytes())
			g.Expect(err).ToNot(HaveOccurred())
			cert := certs[0]
			g.Expect(cert.SerialNumber).ToNot(Equal(startup[0].SerialNumber))
			g.Expect(cert.Subject.CommonName).To(Equal(startup[0].Subject.CommonName))
			g.Expect(cert.Subject.Organization).To(ConsistOf(startup[0].Subject.Organization))
			g.Expect(cert.DNSNames).To(ConsistOf(startup[0].DNSNames))
			g.Expect(cert.IPAddresses).To(ConsistOf(startup[0].IPAddresses))
			g.Expect(cert.ExtKeyUsage).To(ConsistOf(startup[0].ExtKeyUsage))
			g.Expect(cert.KeyUsage).To(Equal(startup[0].KeyUsage))
			g.Expect(cert.CheckSignatureFrom(caCerts[0])).To(Succeed())
			g.Expect(cert.PublicKey).To(BeComparableTo(key.(crypto.Signer).Public()))
		})
	}
}

func Test_UnitCertReloadAuth(t *testing.T) {
	control, cancel := getCorelessControl(t)
	defer cancel()
	defer testutil.CleanupDataDir(control)
	defer os.Unsetenv("NODE_NAME")

	tests := []struct {
		name     string
		user     string
		password string
		address  string
		status   int
	}{
		{"server token", "server", control.Token, "127.0.0.1", http.StatusOK},
		{"agent token", "node", control.AgentToken, "127.0.0.1", http.StatusForbidden},
		{"remote server", "server", control.Token, "203.0.113.1", http.StatusForbidden},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodPost, CertReloadPath("serving-kube-apiserver"), nil)
			withCertificateRequest(req)
			withClientAddress(req, tt.address)
			req.SetBasicAuth(tt.user, tt.password)
			resp := httptest.NewRecorder()
			control.Runtime.Handler.ServeHTTP(resp, req)
			NewWithT(t).Expect(resp).To(HaveHTTPStatus(tt.status))
		})
	}
}
